patch:
diff --git a/tools/repro-emfile-fix.js b/tools/repro-emfile-fix.js
new file mode 100644
index 0000000..6f58f26
--- /dev/null
+++ b/tools/repro-emfile-fix.js
@@ -0,0 +1,61 @@
+/**
+ * @fileoverview Reproduces EMFILE in ESLint.outputFixes when `--fix` writes more
+ * files than the open-file limit allows (eslint/eslint#19924).
+ * Usage: node tools/repro-emfile-fix.js   (POSIX only; lowers `ulimit -n` for the child)
+ */
+
+"use strict";
+
+const fs = require("node:fs");
+const path = require("node:path");
+const { spawnSync } = require("node:child_process");
+
+const OUTPUT_DIRECTORY = "tmp/emfile-fix-check";
+const FILE_LIMIT = 1024;
+const FILE_COUNT = FILE_LIMIT + 100;
+
+fs.rmSync(OUTPUT_DIRECTORY, { recursive: true, force: true, maxRetries: 8 });
+fs.mkdirSync(OUTPUT_DIRECTORY, { recursive: true });
+
+// no trailing newline, so `eol-last` reports a fix for every file
+for (let i = 0; i < FILE_COUNT; i++) {
+	fs.writeFileSync(
+		`${OUTPUT_DIRECTORY}/file_${i}.js`,
+		`// This is file ${i}`,
+	);
+}
+
+console.log(
+	`Running eslint --fix on ${FILE_COUNT} files with ulimit -n ${FILE_LIMIT}...`,
+);
+const child = spawnSync(
+	"sh",
+	[
+		"-c",
+		`ulimit -n ${FILE_LIMIT} && node bin/eslint.js ${OUTPUT_DIRECTORY} --fix --no-config-lookup --rule "eol-last: [error, always]"`,
+	],
+	{ encoding: "utf8" },
+);
+
+const unfixed = fs
+	.readdirSync(OUTPUT_DIRECTORY)
+	.filter(
+		name =>
+			!fs
+				.readFileSync(path.join(OUTPUT_DIRECTORY, name), "utf8")
+				.endsWith("\n"),
+	);
+
+fs.rmSync(OUTPUT_DIRECTORY, { recursive: true, force: true, maxRetries: 8 });
+
+console.log(`eslint exit code: ${child.status}`);
+console.log(`files left unfixed: ${unfixed.length}/${FILE_COUNT}`);
+
+if (child.status !== 0 || unfixed.length > 0) {
+	const emfile = /Error: EMFILE[^\n]*(\n\s+at [^\n]*)*/u.exec(child.stderr);
+
+	console.error(`❌ Bug reproduced:\n${emfile ? emfile[0] : child.stderr}`);
+	process.exitCode = 1;
+} else {
+	console.log("✅ All files fixed, no EMFILE error.");
+}
